async function exportPng(component=false){try{const node=find(selected);if(component&&!node){notify('Select a component first.');return;}const root=svg('svg',{xmlns:NS,width:scene.canvas.width,height:scene.canvas.height,viewBox:`0 0 ${scene.canvas.width} ${scene.canvas.height}`});if(component){const b=componentPaintBounds(node)||bounds(node),padding=4;root.setAttribute('width',Math.ceil(b.width)+padding*2);root.setAttribute('height',Math.ceil(b.height)+padding*2);root.setAttribute('viewBox',`${b.x-padding} ${b.y-padding} ${Math.ceil(b.width)+padding*2} ${Math.ceil(b.height)+padding*2}`);const g=svg('g',{transform:parentMatrix(node.parent).toString()});const output=createNode(node,true);output.removeAttribute('display');g.append(output);root.append(g);}else{root.append(svg('rect',{width:scene.canvas.width,height:scene.canvas.height,fill:scene.canvas.background||'#171815'}));for(const n of children(null))root.append(createNode(n,true));}const sources=new Map();for(const im of root.querySelectorAll('image')){const src=im.getAttribute('href');if(!sources.has(src))sources.set(src,fetch(src).then(r=>{if(!r.ok)throw Error('Could not load '+src);return r.blob();}).then(blob=>new Promise((resolve,reject)=>{const f=new FileReader();f.onload=()=>resolve(f.result);f.onerror=reject;f.readAsDataURL(blob);})));im.setAttribute('href',await sources.get(src));}const source=new XMLSerializer().serializeToString(root),url=URL.createObjectURL(new Blob([source],{type:'image/svg+xml'})),im=new Image();await new Promise((resolve,reject)=>{im.onload=resolve;im.onerror=reject;im.src=url;});const canvas=document.createElement('canvas');canvas.width=Number(root.getAttribute('width'));canvas.height=Number(root.getAttribute('height'));canvas.getContext('2d').drawImage(im,0,0);URL.revokeObjectURL(url);const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'));if(!blob)throw Error('PNG encoding failed');download(blob,`${generic?'design':'hud'}-${component?node.id:stateId}.png`);notify('PNG exported'+(component?' with a transparent background.':'.'));}catch(e){console.error(e);notify('PNG export failed: '+(e.message||'image rendering failed'));}}
// CSS tokens: pure mapping lives in css-export.js. Files always use the default state, so they do not depend on the view tab.
async function exportCss(list){try{if(!bindings||!window.HudCssExport)throw Error('CSS bindings are unavailable');const api=window.HudCssExport,files=list.map(ff=>[ff,api.buildFile(ff,api.exportTokens(scene,seed,bindings,ff))]);for(const[ff,file]of files){download(new Blob([JSON.stringify(file,null,2)+'\n'],{type:'application/json'}),`${ff}.json`);if(files.length>1)await new Promise(resolve=>setTimeout(resolve,150));}const removed=files.reduce((sum,[,f])=>sum+Object.values(f.tokens).filter(v=>v===null).length,0);notify((files.length>1?'Exported four CSS token files.':`Exported ${FF_LABEL[list[0]]} CSS tokens (${Object.keys(files[0][1].tokens).length}).`)+(removed?` ${removed} reset to the seed export as null (merge removes the override).`:''));}catch(e){notify('CSS export failed: '+e.message);}}
async function importCss(file){try{if(!bindings||!window.HudCssExport)throw Error('CSS bindings are unavailable');const api=window.HudCssExport,data=JSON.parse(await file.text());api.importTokens(data,scene,seed,bindings);remember();const plan=api.importFile(data,scene,seed,bindings);render();save();notify(`Imported ${plan.patches.length} CSS value(s) for ${FF_LABEL[plan.formFactor]}. Undo restores the previous layout.`);}catch(e){notify('CSS import rejected: '+e.message);}}
function resetFormFactor(){remember();if(formFactor==='mobile'){for(const n of scene.nodes){const original=seed.nodes.find(o=>o.id===n.id);if(!original)continue;const keep=n.formFactors,global=Object.fromEntries([...baseKeys].filter(k=>k in n).map(k=>[k,n[k]]));for(const k of Object.keys(n))delete n[k];Object.assign(n,clone(original),global);if(keep)n.formFactors=keep;else delete n.formFactors;}render();save();notify('Mobile layout restored to the seed; names, groups and other form factors kept.');return;}for(const n of scene.nodes){if(n.formFactors&&formFactor in n.formFactors){delete n.formFactors[formFactor];if(!Object.keys(n.formFactors).length)delete n.formFactors;}}render();save();notify(`${FF_LABEL[formFactor]} overrides cleared.`);}
function checkEffect(value,numKeys){if(value===null)return;if(!isObj(value))throw Error('Invalid effect');for(const k of numKeys)if(value[k]!==undefined&&(!Number.isFinite(value[k])||Math.abs(value[k])>100000))throw Error('Invalid effect value: '+k);if(value.color!==undefined&&(typeof value.color!=='string'||!CSS.supports('color',value.color)||value.color.includes('url(')))throw Error('Invalid effect color');}
