async function loadAssets(){const loading=$('loading');loading.hidden=false;loading.replaceChildren(html('span',{},'✦'),html('strong',{},'Loading scene assets…'),html('small',{},'The canvas will appear when the artwork is ready.'));const sources=new Set();for(const n of scene.nodes.filter(n=>n.type==='image')){if(scene.assets[n.asset]?.src)sources.add(assetSource(scene.assets[n.asset].src));for(const view of Object.values(n.states||{}))if(view.asset&&scene.assets[view.asset]?.src)sources.add(assetSource(scene.assets[view.asset].src));}if(!generic&&scene.nodes.length>1)sources.add('reference.png');if(generic&&scene.metadata?.references?.[stateId])sources.add(assetSource(scene.metadata.references[stateId]));let loaded=0;const failures=[];await Promise.all([...sources].map(src=>new Promise(resolve=>{const im=new Image();im.onload=async()=>{try{if(im.decode)await im.decode();}catch(e){}loaded++;loading.querySelector('small').textContent=`Artwork ready: ${loaded} / ${sources.size}`;resolve();};im.onerror=()=>{failures.push(src);loaded++;resolve();};im.src=src;})));if(failures.length){loading.replaceChildren(html('strong',{},'Some artwork could not load'),html('small',{},failures.join(', ')),actions(action('Retry loading',loadAssets),action('Continue editing',()=>{loading.hidden=true;})));notify(`${failures.length} artwork file(s) could not load.`);}else{await waitCanvasImages();loading.hidden=true;}}
